import java.util.*;

class Solution {
  public String minAbbreviation(String target, String[] dictionary) {
    int m = target.length();
    // only same-length words can collide; a kept letter must differ from each such word somewhere
    List<Integer> diffs = new ArrayList<>();
    for (String w : dictionary) {
      if (w.length() != m) continue;
      int diff = 0;
      for (int i = 0; i < m; i++) if (w.charAt(i) != target.charAt(i)) diff |= 1 << i;
      diffs.add(diff);
    }
    if (diffs.isEmpty()) return String.valueOf(m);
    int bestMask = (1 << m) - 1, bestLen = m;
    for (int mask = 0; mask < (1 << m); mask++) { // bit i set = keep letter i
      int len = abbrLength(mask, m);
      if (len >= bestLen) continue;
      boolean ok = true;
      for (int d : diffs)
        if ((mask & d) == 0) {
          ok = false;
          break;
        }
      if (ok) {
        bestLen = len;
        bestMask = mask;
      }
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < m; ) {
      if ((bestMask >> i & 1) == 1) sb.append(target.charAt(i++));
      else {
        int j = i;
        while (j < m && (bestMask >> j & 1) == 0) j++;
        sb.append(j - i);
        i = j;
      }
    }
    return sb.toString();
  }

  // kept letters plus one per run of abbreviated letters
  private int abbrLength(int mask, int m) {
    int len = 0;
    for (int i = 0; i < m; ) {
      if ((mask >> i & 1) == 1) i++;
      else while (i < m && (mask >> i & 1) == 0) i++;
      len++;
    }
    return len;
  }
}
